mapper.select:
SELECT e.stu_id, COALESCE(u.real_name, CONCAT('学生', e.stu_id)) AS student_name, e.tag, SUM(e.error_count) AS error_count FROM my_error_book e LEFT JOIN my_student s ON e.stu_id = s.stu_id LEFT JOIN my_sys_user u ON s.user_id = u.user_id WHERE e.is_mastered = 0 AND e.tag IS NOT NULL
AND DATE(e.last_wrong_time) = #{date}
GROUP BY e.stu_id, e.tag ORDER BY e.stu_id, error_count DESC
